        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug is caused by the use of a pointer (`tunnel`) that has been freed by the `tb_pci_free(tunnel);` function. After freeing the pointer, the code attempts to add it to a list using `list_add(&tunnel->list, &tcm->tunnel_list);`, which leads to a use-after-free condition, potentially causing crashes or undefined behavior.

        Commit message:
        thunderbolt: tb: fix use after free in
 tb_activate_pcie_devices
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Add a ̣̣continue statement in order to avoid using a previously
free'd pointer tunnel in list_add.

Addresses-Coverity-ID: 1415336
Fixes: 9d3cce0b6136 ("thunderbolt: Introduce thunderbolt bus and connection manager")
Signed-off-by: Gustavo A. R. Silva <garsilva@embeddedor.com>
Acked-by: Mika Westerberg <mika.westerberg@linux.intel.com>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>  

        Patch:
          */
 static void tb_activate_pcie_devices(struct tb *tb)
 {
 	int i;
 	int cap;
 	u32 data;
 	struct tb_switch *sw;
 	struct tb_port *up_port;
 	struct tb_port *down_port;
 	struct tb_pci_tunnel *tunnel;
 	struct tb_cm *tcm = tb_priv(tb);

 	/* scan for pcie devices at depth 1*/
 	for (i = 1; i <= tb->root_switch->config.max_port_number; i++) {
 		if (tb_is_upstream_port(&tb->root_switch->ports[i]))
 			continue;
 		if (tb->root_switch->ports[i].config.type != TB_TYPE_PORT)
 			continue;
 		if (!tb->root_switch->ports[i].remote)
 			continue;
 		sw = tb->root_switch->ports[i].remote->sw;
 		up_port = tb_find_pci_up_port(sw);
 		if (!up_port) {
 			tb_sw_info(sw, "no PCIe devices found, aborting\n");
 			continue;
 		}

 		/* check whether port is already activated */
 		cap = tb_port_find_cap(up_port, TB_PORT_CAP_ADAP);
 		if (cap < 0)
 			continue;
 		if (tb_port_read(up_port, &data, TB_CFG_PORT, cap, 1))
 			continue;
 		if (data & 0x80000000) {
 			tb_port_info(up_port,
 				     "PCIe port already activated, aborting\n");
 			continue;
 		}

 		down_port = tb_find_unused_down_port(tb->root_switch);
 		if (!down_port) {
 			tb_port_info(up_port,
 				     "All PCIe down ports are occupied, aborting\n");
 			continue;
 		}
 		tunnel = tb_pci_alloc(tb, up_port, down_port);
 		if (!tunnel) {
 			tb_port_info(up_port,
 				     "PCIe tunnel allocation failed, aborting\n");
 			continue;
 		}

 		if (tb_pci_activate(tunnel)) {
 			tb_port_info(up_port,
 				     "PCIe tunnel activation failed, aborting\n");
 			tb_pci_free(tunnel);
+			continue;
 		}

 		list_add(&tunnel->list, &tcm->tunnel_list);
 	}
 }



